public class SkillCutting
extends PlayerSkillBase
implements IDigSpeedAffectorSkill {
    public SkillCutting() {
        super(25);
        this.xpCalculator.setBaseFormula("%lvl%^1.5");
    }

    @Override
    public float getDigMultiplier(ItemStack stack, BlockPos pos, PlayerSkillData data) {
        if (pos == null) {
            return 0.0f;
        }
        BlockState b = data.player.m_9236_().m_8055_(pos);
        if (b.canHarvestBlock((BlockGetter)data.player.m_9236_(), pos, data.player) && (b.m_204336_(BlockTags.f_144280_) || b.m_204336_(BlockTags.f_144281_)) && data.player.m_21205_().m_41691_(b) > 0.0f) {
            return (float)data.getSkillLevel(this) / 8.0f;
        }
        return 0.0f;
    }
}

